import { canvasFor } from "@/lib/design/canvas";
import {
  BLANK_MAX_BYTES_PER_PIXEL,
  bytesPerPixel,
} from "@/lib/design/quality/checks";
import { renderCompositeDesign } from "@/lib/design/render/composite";
import { SQUARE_MARK } from "@/lib/design/render/logo-fixtures";
import { encodePngRgba } from "@/lib/images/png-pixels";
import type { DesignJudgeEvalCase } from "./cases";

/**
 * The bytes each case hands the judge.
 *
 * Rendered locally through the real composite path rather than generated by an
 * image model: the judge is the thing being measured, and a paid plate per
 * case would make the lane cost an image generation per run for pixels that
 * only need to be a real design. The plate is procedural and seeded, so the
 * same case produces the same bytes on every run and a changed acceptance rate
 * is the model's, not the fixture's.
 *
 * `qa-reports/eval` holds real renders from earlier lanes, but it is
 * gitignored — a lane that depends on them passes here and fails in a fresh
 * checkout.
 */

/** Deterministic noise. A plate that compresses to nothing would fail the
 *  blank-frame floor the render is supposed to clear. */
function seededPlate(width: number, height: number): Uint8Array {
  const pixels = new Uint8Array(width * height * 4);
  let seed = 0x2f6e2b1;
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff;
      const grain = (seed >>> 16) & 0x3f;
      const at = (y * width + x) * 4;
      // A warm dusk gradient under the grain, so the frame reads as a scene.
      pixels[at] = Math.min(255, (40 + ((y / height) * 150 + grain)) | 0);
      pixels[at + 1] = Math.min(255, (30 + ((y / height) * 90 + grain)) | 0);
      pixels[at + 2] = Math.min(255, (60 + ((x / width) * 70 + grain)) | 0);
      pixels[at + 3] = 255;
    }
  }
  return encodePngRgba({ width, height, pixels });
}

/** A flat field, which is what the blank-frame fault means. */
function flatFrame(width: number, height: number): Uint8Array {
  const pixels = new Uint8Array(width * height * 4);
  for (let at = 0; at < pixels.length; at += 4) {
    pixels[at] = 15;
    pixels[at + 1] = 23;
    pixels[at + 2] = 42;
    pixels[at + 3] = 255;
  }
  return encodePngRgba({ width, height, pixels });
}

export interface RenderedFixture {
  bytes: Uint8Array | null;
  /** Bytes per pixel, so the report can show that a "render" case really is
   *  above the floor and a "flat" case really is below it. */
  density: number | null;
}

export async function imageForCase(
  evalCase: DesignJudgeEvalCase,
): Promise<RenderedFixture> {
  const canvas = canvasFor(evalCase.spec.aspectRatio);

  if (evalCase.image === "none") return { bytes: null, density: null };

  if (evalCase.image === "flat") {
    const bytes = flatFrame(canvas.width, canvas.height);
    return { bytes, density: bytesPerPixel(bytes.length, canvas) };
  }

  const { bytes } = await renderCompositeDesign({
    spec: evalCase.spec,
    brand: evalCase.brand,
    plate: {
      bytes: seededPlate(canvas.width / 2, canvas.height / 2),
      contentType: "image/png",
    },
    logo: evalCase.hasLogo
      ? {
          bytes: SQUARE_MARK(),
          contentType: "image/png",
          /* What the loader's probe would have measured. Mid-dark on both
             ends: a flat mark, which is the case the unreadable-logo fault
             describes. */
          darkest: 0.185,
          lightest: 0.185,
          aspect: 1,
        }
      : null,
  });

  const density = bytesPerPixel(bytes.length, canvas);
  if (density < BLANK_MAX_BYTES_PER_PIXEL) {
    throw new Error(
      `${evalCase.id}: the rendered fixture is itself a blank frame (${density.toFixed(4)} B/px) — the judge would be shown nothing`,
    );
  }
  return { bytes, density };
}
